<?php
namespace App\Modules\Canteen\Http\Controllers;
use App\Http\Controllers\Controller;
use App\Modules\Canteen\Services\{CanteenAccess as Access,Ordering};
use Illuminate\Http\Request;
use Illuminate\Support\Facades\DB;
use App\Models\User;
use App\Modules\Canteen\Events\OrderChanged;
class OrderController extends Controller {
 private function target(Request $r,array $v):User { $targetId=(int)($v['target_user_id']??$r->user()->id); if($targetId!==$r->user()->id) Access::requireRole($r,$v['company_id'],['admin','kitchen']); $target=User::findOrFail($targetId); abort_unless(DB::table('canteen_profiles')->where('company_id',$v['company_id'])->where('user_id',$targetId)->where('eligible',true)->exists(),422,'This employee is not eligible for Canteen benefits.'); $r->attributes->set('canteen.target_user_id',$targetId); return $target; }
 private function selection(Request $r):array {$v=$r->validate(['company_id'=>'required|integer','lines'=>'required|array|min:1|max:50','lines.*.item_id'=>'required|integer|distinct','lines.*.quantity'=>'required|integer|min:1|max:100','target_user_id'=>'nullable|integer','initial_status'=>'nullable|in:confirmed,preparing,ready']);$v['company_id']=(int)$v['company_id'];$v['lines']=array_map(fn($line)=>['item_id'=>(int)$line['item_id'],'quantity'=>(int)$line['quantity']],$v['lines']);usort($v['lines'],fn($a,$b)=>$a['item_id']<=>$b['item_id']);return $v;}
 public function quote(Request $r){$v=$this->selection($r);Access::company($r,$v['company_id']);$this->target($r,$v);$quote=Ordering::quote($r,$v['company_id'],$v['lines']);return response()->json($quote+['quote_token'=>Ordering::token($r,$v['company_id'],$quote)]);}
 public function store(Request $r){$v=$this->selection($r);$validated=$r->validate(['request_key'=>'required|uuid','quote_token'=>'required|string|size:64']);$key=$validated['request_key'];Access::company($r,$v['company_id']);abort_unless($r->user(),422,'Use an employee account to order.');$target=$this->target($r,$v);$creatorId=$r->user()->id;$order=DB::transaction(function()use($r,$v,$key,$target,$creatorId){DB::table('canteen_profiles')->where('company_id',$v['company_id'])->where('user_id',$target->id)->lockForUpdate()->first();$existing=DB::table('canteen_orders')->where('request_key',$key)->first();if($existing){abort_unless($existing->company_id===$v['company_id']&&$existing->user_id===$target->id,409,'This request key has already been used.');$original=DB::table('canteen_order_lines')->where('order_id',$existing->id)->orderBy('item_id')->get(['item_id','quantity'])->map(fn($line)=>(array)$line)->all();abort_unless($original==$v['lines'],409,'This request key belongs to a different order.');return $existing;}$quote=Ordering::quote($r,$v['company_id'],$v['lines'],true);abort_unless(hash_equals(Ordering::token($r,$v['company_id'],$quote),$r->input('quote_token')),409,'Prices or allowances changed. Review the payable amount again.');$id=DB::table('canteen_orders')->insertGetId(['company_id'=>$v['company_id'],'user_id'=>$target->id,'created_by'=>$creatorId,'request_key'=>$key,'employee_name'=>$target->name,'employee_email'=>$target->email,'level_id'=>$quote['level_id'],'level_name'=>$quote['level_name'],'status'=>$v['initial_status']??'confirmed','payment_status'=>$quote['employee_share']>0?'unpaid':'not_required','gross'=>$quote['gross'],'company_share'=>$quote['company_share'],'employee_share'=>$quote['employee_share'],'created_at'=>now(),'updated_at'=>now()]);foreach($quote['lines'] as $line){DB::table('canteen_order_lines')->insert($line+['order_id'=>$id]);if($line['stock_tracked']){$balance=DB::table('canteen_items')->where('id',$line['item_id'])->value('stock_quantity')-$line['quantity'];DB::table('canteen_items')->where('id',$line['item_id'])->update(['stock_quantity'=>$balance,'updated_at'=>now()]);DB::table('canteen_stock_movements')->insert(['company_id'=>$v['company_id'],'item_id'=>$line['item_id'],'order_id'=>$id,'quantity_change'=>-$line['quantity'],'balance'=>$balance,'reason'=>'Order confirmed','created_at'=>now()]);}}Access::audit($r,$v['company_id'],'order.confirmed',['order_id'=>$id,'gross'=>$quote['gross']]);event(new OrderChanged($v['company_id'],$id,'created'));return DB::table('canteen_orders')->find($id);});return response()->json(['message'=>'Order confirmed.','order'=>$order],201);}
 private function order(Request $r,int $id){$order=DB::table('canteen_orders')->find($id);abort_unless($order,404);$role=Access::role($r,$order->company_id);abort_if($role==='employee'&&$order->user_id!==$r->user()?->id,403);return $order;}
 public function index(Request $r){$v=$r->validate(['company_id'=>'required|integer','page'=>'sometimes|integer|min:1','status'=>'nullable|in:confirmed,preparing,ready,delivered,cancelled']);$role=Access::role($r,$v['company_id']);$q=DB::table('canteen_orders')->where('company_id',$v['company_id']);if($role==='employee')$q->where('user_id',$r->user()->id);if(!empty($v['status']))$q->where('status',$v['status']);$page=$q->orderByDesc('id')->paginate(20);$lines=DB::table('canteen_order_lines')->whereIn('order_id',collect($page->items())->pluck('id'))->get()->groupBy('order_id');foreach($page->items() as $order){$order->lines=$lines->get($order->id,collect());if($role==='kitchen'){unset($order->employee_email,$order->gross,$order->company_share,$order->employee_share,$order->payment_status);$order->lines=$order->lines->map(fn($l)=>['item_name'=>$l->item_name,'quantity'=>$l->quantity]);}}return response()->json($page);}
 public function update(Request $r,int $id){$order=$this->order($r,$id);$v=$r->validate(['status'=>'sometimes|in:preparing,ready,delivered,cancelled','payment_status'=>'sometimes|in:paid']);$role=Access::role($r,$order->company_id);abort_if(!count($v),422,'Select an action.');if(isset($v['payment_status']))Access::requireRole($r,$order->company_id,['admin','cashier']);if(isset($v['status']))Access::requireRole($r,$order->company_id,$v['status']==='cancelled'?['admin','cashier']:['admin','kitchen']);DB::transaction(function()use($r,$id,$v,$order){$current=DB::table('canteen_orders')->where('id',$id)->lockForUpdate()->first();$next=['confirmed'=>'preparing','preparing'=>'ready','ready'=>'delivered'];if(isset($v['status'])){if($v['status']==='cancelled'){abort_unless(in_array($current->status,['confirmed','preparing'])&&$current->payment_status!=='paid',422,'Only unpaid, unfulfilled orders can be cancelled.');foreach(DB::table('canteen_order_lines')->where('order_id',$id)->where('stock_tracked',true)->orderBy('item_id')->get() as $line){$item=DB::table('canteen_items')->where('id',$line->item_id)->lockForUpdate()->first();$balance=$item->stock_quantity+$line->quantity;DB::table('canteen_items')->where('id',$item->id)->update(['stock_quantity'=>$balance,'updated_at'=>now()]);DB::table('canteen_stock_movements')->insert(['company_id'=>$order->company_id,'item_id'=>$item->id,'order_id'=>$id,'quantity_change'=>$line->quantity,'balance'=>$balance,'reason'=>'Order cancelled','created_at'=>now()]);}}else abort_unless(($next[$current->status]??null)===$v['status'],422,'Invalid order status transition.');}if(isset($v['payment_status']))abort_if($current->status==='cancelled'||$current->employee_share<=0,422,'Payment is not required for this order.');DB::table('canteen_orders')->where('id',$id)->update($v+['updated_at'=>now()]);Access::audit($r,$order->company_id,'order.updated',['order_id'=>$id,'changes'=>$v]);event(new OrderChanged((int)$order->company_id,$id,'updated'));});return response()->json(['message'=>'Order updated.']);}
 public function receipt(Request $r,int $id,string $kind){$order=$this->order($r,$id);abort_unless(in_array($kind,['kitchen','cashier']),404);abort_if(Access::role($r,$order->company_id)==='kitchen'&&$kind==='cashier',403);$lines=DB::table('canteen_order_lines')->where('order_id',$id)->get();Access::audit($r,$order->company_id,'receipt.opened',['order_id'=>$id,'kind'=>$kind]);$company=DB::table('communication_companies')->where('id',$order->company_id)->value('name');$timezone=DB::table('canteen_settings')->where('company_id',$order->company_id)->value('timezone')??'Asia/Karachi';return view('canteen-receipt',compact('order','lines','kind','company','timezone'));}
 public function report(Request $r){
  $v=$r->validate(['company_id'=>'required|integer','from'=>'required|date','to'=>'required|date|after_or_equal:from','group_by'=>'sometimes|in:item,category,employee,level,day,order','page'=>'sometimes|integer|min:1|max:100000','user_id'=>'nullable|integer','level_id'=>'nullable|integer','category_id'=>'nullable|integer','item_id'=>'nullable|integer']);Access::requireRole($r,$v['company_id'],['admin','cashier']);
  $zone=DB::table('canteen_settings')->where('company_id',$v['company_id'])->value('timezone')??'Asia/Karachi';$from=\Carbon\Carbon::parse($v['from'],$zone)->startOfDay()->setTimezone(config('app.timezone'));$to=\Carbon\Carbon::parse($v['to'],$zone)->endOfDay()->setTimezone(config('app.timezone'));
  $q=DB::table('canteen_orders')->where('company_id',$v['company_id'])->whereBetween('created_at',[$from,$to]);foreach(['user_id','level_id'] as $key)if(!empty($v[$key]))$q->where($key,$v[$key]);
  if(!empty($v['category_id'])||!empty($v['item_id']))$q->whereIn('id',DB::table('canteen_order_lines')->when(!empty($v['category_id']),fn($l)=>$l->where('category_id',$v['category_id']))->when(!empty($v['item_id']),fn($l)=>$l->where('item_id',$v['item_id']))->select('order_id'));
  $history=clone $q;$q->where('status','!=','cancelled');
  $summary=(clone $q)->selectRaw('COUNT(*) as orders,COUNT(DISTINCT user_id) as employees,COALESCE(SUM(gross),0) as gross,COALESCE(SUM(company_share),0) as company_share,COALESCE(SUM(employee_share),0) as employee_share')->first();
  $lines=DB::table('canteen_order_lines')->whereIn('order_id',(clone $q)->select('id'));foreach(['category_id','item_id'] as $key)if(!empty($v[$key]))$lines->where($key,$v[$key]);$group=$v['group_by']??'employee';$totals=(clone $lines)->selectRaw('COALESCE(SUM(gross),0) as gross,COALESCE(SUM(company_share),0) as company_share,COALESCE(SUM(employee_share),0) as employee_share')->first();foreach(['gross','company_share','employee_share'] as $key)$summary->$key=$totals->$key;
  if($group==='order'){return $this->detailedReport($r,$v,$history,$summary,$zone);}
  if(in_array($group,['item','category'])){$name=$group==='item'?'item_name':'category_name';$rows=(clone $lines)->selectRaw($name.' as label,SUM(quantity) as quantity,SUM(gross) as gross,SUM(company_share) as company_share,SUM(employee_share) as employee_share')->groupBy($name)->orderByDesc('quantity')->get();}
  else {$by=match($group){'employee'=>'canteen_orders.employee_name','level'=>'canteen_orders.level_name',default=>'canteen_orders.created_at'};$rowsQuery=DB::table('canteen_orders')->join('canteen_order_lines as lines','lines.order_id','=','canteen_orders.id')->whereIn('canteen_orders.id',(clone $q)->select('id'));foreach(['category_id','item_id'] as $key)if(!empty($v[$key]))$rowsQuery->where('lines.'.$key,$v[$key]);if($group==='day')$rowsQuery->selectRaw('DATE(canteen_orders.created_at AT TIME ZONE ? AT TIME ZONE ?) as label',[config('app.timezone'),$zone])->groupBy('label');else $rowsQuery->selectRaw($by.' as label')->groupBy($by)->groupBy($group==='employee'?'canteen_orders.user_id':'canteen_orders.level_id');if($group==='employee')$rowsQuery->selectRaw('canteen_orders.level_name as level_name,lines.item_name as product_name,SUM(lines.quantity) as item_quantity')->groupBy('canteen_orders.level_id','canteen_orders.level_name','lines.item_id','lines.item_name');$rows=$rowsQuery->selectRaw('COUNT(DISTINCT canteen_orders.id) as quantity,SUM(lines.gross) as gross,SUM(lines.company_share) as company_share,SUM(lines.employee_share) as employee_share')->orderBy('label')->get();}
  $items=$lines->selectRaw('item_name,category_name,SUM(quantity) as quantity,SUM(gross) as gross,SUM(company_share) as company_share,SUM(employee_share) as employee_share')->groupBy('item_name','category_name')->orderByDesc('quantity')->get();
  return response()->json(['summary'=>$summary,'items'=>$items,'rows'=>$rows,'group_by'=>$group]);
 }
 private function detailedReport(Request $r,array $v,$history,$summary,string $zone){
  $total=(clone $history)->count();$page=(int)($v['page']??1);$query=(clone $history)->orderByDesc('created_at')->orderByDesc('id');if(!$r->attributes->get('canteen.export'))$query->skip(($page-1)*20)->take(20);$orders=$query->get();
  $lines=DB::table('canteen_order_lines')->whereIn('order_id',$orders->pluck('id'));foreach(['category_id','item_id'] as $key)if(!empty($v[$key]))$lines->where($key,$v[$key]);$items=$lines->orderBy('id')->get()->groupBy('order_id');
  $rows=$orders->map(function($order)use($items,$zone){$details=$items->get($order->id,collect());$cancelled=$order->status==='cancelled';return ['order_id'=>$order->id,'ordered_at'=>\Carbon\Carbon::parse($order->created_at,config('app.timezone'))->setTimezone($zone)->toIso8601String(),'employee_name'=>$order->employee_name,'level_name'=>$order->level_name,'status'=>$order->status,'payment_status'=>$order->payment_status,'products'=>$details->map(fn($line)=>['name'=>$line->item_name,'quantity'=>$line->quantity,'unit_price'=>$line->unit_price])->values(),'item_quantity'=>$details->sum('quantity'),'gross'=>$cancelled?0:$details->sum('gross'),'company_share'=>$cancelled?0:$details->sum('company_share'),'employee_share'=>$cancelled?0:$details->sum('employee_share')];});
  return response()->json(['summary'=>$summary,'items'=>[],'rows'=>$rows,'group_by'=>'order','total'=>$total,'page'=>$page,'per_page'=>20]);
 }
 private function exportTable(array $data):array {
  if($data['group_by']==='order'){$headers=['Order number','Date/time','Employee name','Benefit level','Products and quantities','Units ordered','Total value','Company contribution','Employee contribution','Order status','Payment status'];$rows=array_map(fn($row)=>[$row['order_id'],$row['ordered_at'],$row['employee_name'],$row['level_name'],implode('; ',array_map(fn($product)=>$product['name'].' x '.$product['quantity'],$row['products'])),$row['item_quantity'],$row['gross'],$row['company_share'],$row['employee_share'],$row['status'],$row['payment_status']],$data['rows']);}
  else {$employee=$data['group_by']==='employee';$headers=array_merge([$employee?'Employee name':'Name / Date'],$employee?['Benefit level','Ordered product','Total units']:[],[in_array($data['group_by'],['item','category'])?'Total units':'Number of orders','Total value','Company contribution','Employee contribution']);$rows=array_map(fn($row)=>array_merge([$row['label']],$employee?[$row['level_name'],$row['product_name'],$row['item_quantity']]:[],[$row['quantity'],$row['gross'],$row['company_share'],$row['employee_share']]),$data['rows']);}
  return [$headers,...$rows];
 }
 public function export(Request $r,string $format){
  abort_unless(in_array($format,['csv','xlsx','pdf']),404);$r->attributes->set('canteen.export',true);$data=$this->report($r)->getData(true);$table=$this->exportTable($data);Access::audit($r,(int)$r->input('company_id'),'report.exported',['format'=>$format,'from'=>$r->input('from'),'to'=>$r->input('to')]);
  if($format==='pdf'){$pdf=new \Dompdf\Dompdf(['isRemoteEnabled'=>false]);$pdf->loadHtml(view('canteen-report',['data'=>$data,'table'=>$table,'from'=>$r->input('from'),'to'=>$r->input('to')])->render());$pdf->setPaper('a4','landscape');$pdf->render();return response($pdf->output(),200,['Content-Type'=>'application/pdf','Content-Disposition'=>'attachment; filename="canteen-report.pdf"']);}
  if($format==='csv')return response()->streamDownload(function()use($table){$out=fopen('php://output','w');fwrite($out,"\xEF\xBB\xBF");foreach($table as $row)fputcsv($out,array_map(fn($value)=>preg_match('/^[=+@-]/',(string)$value)?"'".$value:$value,$row));fclose($out);},'canteen-report.csv',['Content-Type'=>'text/csv; charset=UTF-8']);
  return response()->streamDownload(function()use($table){$book=new \PhpOffice\PhpSpreadsheet\Spreadsheet();$sheet=$book->getActiveSheet();foreach($table as $i=>$row)foreach($row as $j=>$value)$sheet->setCellValueExplicit(\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex($j+1).($i+1),(string)$value,\PhpOffice\PhpSpreadsheet\Cell\DataType::TYPE_STRING);$sheet->freezePane('A2');$sheet->getStyle('A1:'.\PhpOffice\PhpSpreadsheet\Cell\Coordinate::stringFromColumnIndex(count($table[0])).'1')->getFont()->setBold(true);(new \PhpOffice\PhpSpreadsheet\Writer\Xlsx($book))->save('php://output');$book->disconnectWorksheets();},'canteen-report.xlsx',['Content-Type'=>'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet']);
 }
}
